//! The native convention's declarations (`TODO.md` §97, `docs/research/
//! declared-conventions.md`) are what each machine's constants say:
//! `fixpt-runtime/src/native-arm64.conv` and `native-x86_64.conv`, which
//! both checkers compare a program's `define-convention` with on that
//! machine, are generated by `fixpt_native::direct::native_convention_of`.
//! `FIXPT_BLESS=1` rewrites them.

#[test]
fn the_declarations_are_generated_from_the_machines() {
    for target in ["arm64", "x86_64"] {
        let path = format!("{}/../fixpt-runtime/src/native-{target}.conv", env!("CARGO_MANIFEST_DIR"));
        let made = fixpt_native::direct::native_convention_of(target);
        if std::env::var_os("FIXPT_BLESS").is_some() {
            std::fs::write(&path, &made).expect("written");
        }
        let file = std::fs::read_to_string(&path).expect("readable");
        assert_eq!(file, made, "{path} is out of date: FIXPT_BLESS=1 cargo test -p fixpt-native --test convention");
    }
}
